# Not in the book: the newest upstream release, built with its own build
# script (hack/make-rules/build.sh, what "make WHAT=cmd/kubectl" runs) from
# the release's source tarball, offline from the vendored modules. The
# version stamps come from the tarball itself (hack/lib/version.sh is
# filled in by git archive). Upstream's manual pages are generated by
# cmd/genman, which links every Kubernetes component; they are left out.
unpack() {
    # The tarball has no top-level directory.
    tar -xf "$SOURCES/$PKG_SOURCE" --no-same-owner --no-same-permissions
}

build() {
    # FORCE_HOST_GO: build with this Go instead of downloading the version
    # in .go-version. Caches go to _output/local/go in the source tree.
    export FORCE_HOST_GO=1 GOTOOLCHAIN=local GOTELEMETRY=off
    export GOFLAGS="-mod=vendor -buildmode=pie"
    export KUBE_BUILD_PLATFORMS=linux/amd64
    hack/make-rules/build.sh cmd/kubectl

    local kubectl=_output/local/bin/linux/amd64/kubectl
    "$kubectl" completion bash > kubectl.bash
    "$kubectl" completion zsh > _kubectl
    "$kubectl" completion fish > kubectl.fish
}

package() {
    install -Dm755 _output/local/bin/linux/amd64/kubectl "$DESTDIR/usr/bin/kubectl"
    install -Dm644 kubectl.bash "$DESTDIR/usr/share/bash-completion/completions/kubectl"
    install -Dm644 _kubectl "$DESTDIR/usr/share/zsh/site-functions/_kubectl"
    install -Dm644 kubectl.fish "$DESTDIR/usr/share/fish/vendor_completions.d/kubectl.fish"
}
